		t.Fatalf("state file changed despite save failure")
	}
	if leftovers, _ := filepath.Glob(filepath.Join(filepath.Dir(state), ".govflow-state-*")); len(leftovers) != 0 {
		t.Fatalf("failed vote left temporary file(s): %v", leftovers)
