		t.Fatalf("balances must stay unchanged, code=%d:\n%s", code, so)
	}
	if so, _, code = runCLI(t, binary, state, "receipts", "--json"); code != 0 ||
		strings.TrimSpace(so) != "[]" {
		t.Fatalf("no receipts may exist, code=%d:\n%s", code, so)
	}
}

